changeSet.sql:
CREATE TABLE nigerian_states (
    code      varchar(8)  NOT NULL PRIMARY KEY,
    name      varchar(64) NOT NULL UNIQUE,
    aliases   text[]      NOT NULL DEFAULT '{}',
    boundary  geometry(Polygon, 4326) NOT NULL
);
CREATE INDEX idx_nigerian_states_boundary ON nigerian_states USING GIST (boundary);
COMMENT ON TABLE nigerian_states IS
    'Reference data. GRID3 operational state boundaries via geoBoundaries (CC BY 4.0, attribution required). Not the legal boundary record.';

ALTER TABLE estates ADD COLUMN state_code varchar(8) REFERENCES nigerian_states (code);
ALTER TABLE estates ADD COLUMN state_override_at timestamp(6) with time zone;
ALTER TABLE estates ADD COLUMN state_override_by uuid;
ALTER TABLE estates ADD COLUMN state_override_reason text;
ALTER TABLE estates ADD CONSTRAINT chk_estates_state_override_complete
    CHECK ((state_override_at IS NULL) = (state_override_by IS NULL)
           AND (state_override_at IS NULL) = (state_override_reason IS NULL));

UPDATE estates e
   SET state_code = s.code, state = s.name
  FROM nigerian_states s
 WHERE e.state IS NOT NULL
   AND lower(btrim(regexp_replace(e.state, '\s+state\s*$', '', 'i')))
       IN (lower(s.name), lower(s.code))
    OR (e.state IS NOT NULL
        AND lower(btrim(regexp_replace(e.state, '\s+state\s*$', '', 'i'))) = ANY (s.aliases));

COMMENT ON COLUMN estates.state_code IS
    'ISO 3166-2 code of the declared state (nigerian_states). The SB-1 boundary check keys on this.';
COMMENT ON COLUMN estates.state_override_at IS
    'Set by a Super Admin when the declared state was verified by a person (a disputed border): the SB-1 boundary check is skipped.';

changeSet.rollback:
ALTER TABLE estates DROP CONSTRAINT chk_estates_state_override_complete;
ALTER TABLE estates DROP COLUMN state_override_reason;
ALTER TABLE estates DROP COLUMN state_override_by;
ALTER TABLE estates DROP COLUMN state_override_at;
ALTER TABLE estates DROP COLUMN state_code;
